```python
@classmethod
def from_codes(cls, codes, categories=None, ordered=None, dtype=None):
    dtype = CategoricalDtype._from_values_or_dtype(
        categories=categories, ordered=ordered, dtype=dtype
    )
    if dtype.categories is None:
        msg = (
            "The categories must be provided in 'categories' or "
            "'dtype'. Both were None."
        )
        raise ValueError(msg)

    codes = np.asarray(codes)  # Convert to a NumPy array
    if len(codes):
        # Check if codes contain NA values, which are represented as <NA> for Int64
        if is_integer_dtype(codes) and np.any(pd.isna(codes)):
            raise ValueError("codes cannot contain NA values")
        elif not is_integer_dtype(codes):
            raise ValueError("codes need to be array-like integers")

        if codes.max() >= len(dtype.categories) or codes.min() < -1:
            raise ValueError("codes need to be between -1 and len(categories)-1")

    return cls(codes, dtype=dtype, fastpath=True)
```
